use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let bytes = input.as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect();
    let mut hex = String::new();
    for &b in &bytes {
        hex.push_str(format!("{:x}", b).to_lowercase());
    }
    Value::String(hex)
}
